{
  "technical_and_design_decisions": [
    "Externalized components will be published as separate Go modules under github.com/hyperledger/ (e.g., fabric-protos, fabric-common, fabric-ledger, fabric-ccprovider).",
    "New modules will be maintained within the Hyperledger Fabric repository (monorepo) using Go workspaces to simplify CI/CD and versioning.",
    "SDK modifications to Fabric code will be upstreamed to Fabric before externalization to avoid forks.",
    "The temporary workaround for chaincode go.mod (U6) will be implemented behind a build tag 'legacygo' and documented as deprecated.",
    "Versioning: new modules will start at v0.1.0 and follow semantic versioning; Fabric and SDK will depend on specific versions.",
    "Backward compatibility: existing Fabric and SDK public APIs will be preserved; only internal imports change."
  ],
  "assumptions": [
    "The developer has write access to both Fabric and Fabric Go SDK repositories.",
    "Both codebases use Go modules (go.mod) and can depend on external modules via go.mod.",
    "Externalized modules will be hosted in the same GitHub organization (hyperledger) and importable via go.mod.",
    "Effort includes only development work, not code review or approval processes.",
    "SDK modifications are relatively small and can be merged upstream within the estimated time.",
    "No major refactoring of Fabric core architecture is required beyond moving packages.",
    "Testing infrastructure (unit tests, integration tests) exists and can be extended.",
    "The temporary workaround (U6) is limited to honoring go.mod in chaincode packages and can be implemented in the chaincode packaging logic."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Design and planning",
      "activity_description": "Analyze all user stories, map component dependencies, define module boundaries, create migration plan, and coordinate with stakeholders.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A2",
      "activity_name": "Create fabric-protos module (gossip/protoext, discovery client)",
      "activity_description": "Extract gossip/protoext and discovery client code from Fabric into a new Go module (github.com/hyperledger/fabric-protos). Incorporate SDK modifications (U1). Update Fabric to depend on new module.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A3",
      "activity_name": "Create fabric-common module (cauthdsl, common utilities, configtxgen, configtxlator)",
      "activity_description": "Extract cauthdsl (U2), common utilities (U5), configtxgen (U7), and configtxlator (U8) into a new Go module (github.com/hyperledger/fabric-common). Merge SDK modifications. Update Fabric to use new module.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A4",
      "activity_name": "Create fabric-ledger module (ledger structures)",
      "activity_description": "Extract ledger structures (U4) into a new Go module (github.com/hyperledger/fabric-ledger). Update Fabric to depend on new module.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A5",
      "activity_name": "Create fabric-ccprovider module (ccprovider structures)",
      "activity_description": "Extract ccprovider structures (U3) into a new Go module (github.com/hyperledger/fabric-ccprovider). Update Fabric to depend on new module.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A6",
      "activity_name": "Refactor Fabric core to use new modules",
      "activity_description": "Update all internal Fabric imports to use the new externalized modules. Fix any compilation issues, adjust internal APIs, and ensure all tests pass.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A7",
      "activity_name": "Update Fabric Go SDK to depend on new modules",
      "activity_description": "Replace all copied code in SDK (internal/github.com/hyperledger/fabric/... and third_party/...) with imports from the new externalized modules. Update go.mod, fix any API differences, and remove duplicated directories.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A8",
      "activity_name": "Implement temporary go.mod workaround for chaincode packages (U6)",
      "activity_description": "Add a build tag 'legacygo' to honor go.mod files in chaincode packages. Implement logic in chaincode packaging, document as deprecated, and add a feature flag to disable.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A9",
      "activity_name": "Update unit tests in Fabric",
      "activity_description": "Modify existing unit tests in Fabric to work with the new module structure. Add tests for new module boundaries and ensure coverage.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A10",
      "activity_name": "Update unit tests in SDK",
      "activity_description": "Modify existing unit tests in SDK to use the new externalized modules. Remove tests for deleted copied code. Add tests for new dependency usage.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A11",
      "activity_name": "Integration testing (Fabric + SDK)",
      "activity_description": "Run end-to-end integration tests between Fabric and SDK using the new modules. Verify chaincode deployment, discovery, configtxgen, configtxlator, and ledger operations.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A12",
      "activity_name": "Documentation updates and migration guides",
      "activity_description": "Update READMEs, godoc comments, and create migration guides for SDK users. Document new module imports, versioning, and the temporary workaround deprecation.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A13",
      "activity_name": "CI/CD pipeline updates for new modules",
      "activity_description": "Configure GitHub Actions (or equivalent) for the new modules: build, test, release, and publish to pkg.go.dev. Update Fabric and SDK pipelines to depend on published modules.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A14",
      "activity_name": "Release preparation and version tagging",
      "activity_description": "Tag initial versions (v0.1.0) for all new modules. Update Fabric and SDK go.mod to require specific versions. Create changelogs and release notes.",
      "most_likely_effort": 1
    }
  ],
  "reported_total": {
    "most_likely_effort": 44
  }
}

